const _w = (s) => I18N.w(s);
const I18N_PATTERNS = [
  [/^問題 (\d+) \/ (\d+)$/, ['もんだい $1 / $2', 'Question $1 / $2']],
  [/^正解した問題 (\d+) \/ (\d+)$/, ['せいかいした もんだい $1 / $2', 'Answered correctly: $1 / $2']],
  [/^(\d+) \/ (\d+) 完了$/, ['$1 / $2 できた', '$1 / $2 done']],
  [/^はじめての準備（あと(\d+)つ）$/, ['はじめての じゅんび（あと $1つ）', 'First-time setup ($1 left)']],
  [/^正解は ([ABC])「(.*)」$/, [(m) => `せいかいは ${m[1]}「${_w(m[2])}」`, (m) => `Correct answer: ${m[1]} “${_w(m[2])}”`]],
  [/^(.+)（([\d,]+)か所・([\d.]+)MB）$/, [(m) => `${m[1]}（${m[2]}か所・${m[3]}MB）`, (m) => `${_w(m[1])} (${m[2]} sites, ${m[3]} MB)`]],
  [/^避難場所 ([\d,]+)・避難所 ([\d,]+|未保存（保存し直してください）)・取得日 (.+)$/, [(m) => `ひなん場所 ${m[1]}・ひなんじょ ${m[2]}・データの日 ${m[3]}`, (m) => `Sites ${m[1]} · Centres ${/^[\d,]+$/.test(m[2]) ? m[2] : 'not saved (save again)'} · Data date ${m[3]}`]],
  [/^矢印は北を上にした方角です（位置の誤差：約(\d+)m）$/, ['やじるしは 北が 上の ほうがく です（ずれ：やく $1m）', 'Arrows show direction with north up (location accuracy: about $1 m)']],
  [/^誤差 約(\d+)m$/, ['ずれ やく $1m', 'Accuracy about $1 m']],
  [/^(\d\d:\d\d)（現在）$/, ['$1（いま）', '$1 (now)']], [/^(\d\d:\d\d)（予測）$/, ['$1（よそう）', '$1 (forecast)']],
  [/^(.+)の風$/, [(m) => `${_w(m[1])}の かぜ`, (m) => `${_w(m[1])} wind`]],
  [/^朝の最低 (-?\d+)℃　日中の最高 (-?\d+)℃$/, ['あさの さいてい $1℃　ひるの さいこう $2℃', 'Morning low $1°C, daytime high $2°C']],
  [/^気温（(.+)）$/, ['きおん（$1）', 'Temperature ($1)']], [/^天気予報（(.+)）$/, [(m) => `てんきよほう（${m[1]}）`, (m) => `Weather forecast (${_w(m[1])})`]],
  [/^「(.+)」に対応する近い避難場所$/, [(m) => `「${_w(m[1])}」の ときの ちかい ひなん場所`, (m) => `Nearby sites for: ${_w(m[1])}`]],
  [/^【(.+)】$/, [(m) => `【${_w(m[1])}】`, (m) => `[${_w(m[1])}]`]],
  [/^(.+)（約([\d.]+k?m)）$/, [(m) => `${m[1]}（やく ${m[2]}）`, (m) => `${m[1]} (about ${m[2]})`]],
  [/^(.+)全体$/, [(m) => `${m[1]} ぜんぶ`, (m) => `All of ${m[1]}`]],
  [/^(\d+)月(\d+)日 (\d\d:\d\d) 発表$/, ['$1月$2日 $3 に でた', 'Issued $1/$2 $3']], [/^(\d+)月(\d+)日 (\d\d:\d\d) の観測$/, ['$1月$2日 $3 の かんそく', 'Observed $1/$2 $3']],
  [/^(\d+)月(\d+)日 (\d\d:\d\d) 発表　(.*)$/, ['$1月$2日 $3 に でた　$4', 'Issued $1/$2 $3　$4']],
  [/^最大震度(.+)$/, ['いちばん 大きい しんど $1', 'Max intensity $1']],
  [/^(\d+)時〜 /, [(m) => m.input.replace(/(\d+)時〜 (\d+)%/g, '$1じ〜 $2%'), (m) => m.input.replace(/(\d+)時〜 (\d+)%/g, 'from $1:00 $2%')]],
  [/^(大津波警報|津波警報|津波注意報)が発表されています$/, [(m) => `${_w(m[1])}が でています`, (m) => `${_w(m[1])} in effect`]],
  [/^深さ約(\d+)km$/, ['ふかさ やく $1km', 'Depth about $1 km']],
  [/^(.+)の避難場所 ([\d,]+)か所を保存しました。$/, [(m) => `${m[1]}の ひなん場所 ${m[2]}か所を ほぞん しました。`, (m) => `Saved ${m[2]} evacuation sites in ${_w(m[1])}.`]],
];

